/**
 * The k6 script for a load test, generated by Friday from a plan, never written by the model. It
 * calls only the approved origin (redirects are not followed), with exactly the approved virtual
 * users and duration. Every value from the plan goes in as a JSON literal, so it can't become
 * code.
 */

export const METHODS = ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE'] as const;
export type Method = (typeof METHODS)[number];

/** A request name usable as a k6 tag inside a threshold key. */
export const REQUEST_NAME = /^[A-Za-z0-9 _./-]{1,60}$/;

export interface LoadRequest {
  name: string;
  method: Method;
  /** Path and query on the origin, starting with "/". */
  path: string;
  headers: Record<string, string>;
  body: string | null;
  /** The status that counts as success; null: any 2xx or 3xx. */
  expectStatus: number | null;
}

export interface LoadPlan {
  origin: string;
  requests: LoadRequest[];
  /** Constant load (ignored when stages are given). */
  vus: number;
  durationSeconds: number;
  stages: Array<{ durationSeconds: number; targetVus: number }> | null;
  thinkTimeMs: number;
  thresholds: {
    p95Ms: number | null;
    p99Ms: number | null;
    /** 0–1 */
    errorRate: number | null;
    perRequestP95Ms: Record<string, number>;
  };
}

/**
 * Checks named "status:<request>:<code>" always pass; k6 adds them up across virtual users, which
 * gives the status codes each request got. They are not shown as checks.
 */
export const STATUS_CHECK = 'status:';
/** Likewise "body:<request>:<code>:<start of the body>", for the first unexpected response. */
export const BODY_CHECK = 'body:';

/** Thresholds that only make k6 report per-request numbers; they always pass and are not shown. */
export const INTERNAL_CONDITIONS = new Set(['max>=0', 'rate>=0', 'count>=0']);

/** Seconds of load: the stages added up, or the constant duration. */
export const totalSeconds = (p: Pick<LoadPlan, 'stages' | 'durationSeconds'>) =>
  p.stages ? p.stages.reduce((s, x) => s + x.durationSeconds, 0) : p.durationSeconds;

/** The most virtual users at any time. */
export const peakVus = (p: Pick<LoadPlan, 'stages' | 'vus'>) =>
  p.stages ? Math.max(...p.stages.map((s) => s.targetVus)) : p.vus;

/** The thresholds as k6 writes them, for the card ("p(95)<500" on http_req_duration). */
export function thresholdLines(p: LoadPlan): string[] {
  const t = p.thresholds;
  return [
    ...(t.p95Ms !== null ? [`p(95) < ${t.p95Ms} ms`] : []),
    ...(t.p99Ms !== null ? [`p(99) < ${t.p99Ms} ms`] : []),
    ...(t.errorRate !== null ? [`failed requests < ${(t.errorRate * 100).toFixed(2)}%`] : []),
    ...Object.entries(t.perRequestP95Ms).map(([n, ms]) => `${n}: p(95) < ${ms} ms`),
  ];
}

function thresholds(p: LoadPlan): Record<string, string[]> {
  const t = p.thresholds;
  const out: Record<string, string[]> = {};
  const duration = [
    ...(t.p95Ms !== null ? [`p(95)<${t.p95Ms}`] : []),
    ...(t.p99Ms !== null ? [`p(99)<${t.p99Ms}`] : []),
  ];
  if (duration.length) out.http_req_duration = duration;
  if (t.errorRate !== null) out.http_req_failed = [`rate<${t.errorRate}`];
  for (const r of p.requests) {
    const p95 = t.perRequestP95Ms[r.name];
    out[`http_req_duration{name:${r.name}}`] = p95 !== undefined ? [`p(95)<${p95}`] : ['max>=0'];
    out[`http_req_failed{name:${r.name}}`] = ['rate>=0'];
    out[`http_reqs{name:${r.name}}`] = ['count>=0'];
  }
  return out;
}

function scenario(p: LoadPlan) {
  return p.stages
    ? {
        executor: 'ramping-vus',
        startVUs: 0,
        stages: p.stages.map((s) => ({ duration: `${s.durationSeconds}s`, target: s.targetVus })),
        gracefulRampDown: '10s',
        gracefulStop: '10s',
      }
    : {
        executor: 'constant-vus',
        vus: p.vus,
        duration: `${p.durationSeconds}s`,
        gracefulStop: '10s',
      };
}

const json = (v: unknown, indent = 2) => JSON.stringify(v, null, indent);

export function buildScript(p: LoadPlan): string {
  const requests = p.requests.map((r) => ({
    name: r.name,
    method: r.method,
    path: r.path,
    headers:
      r.body !== null &&
      !Object.keys(r.headers).some((h) => h.toLowerCase() === 'content-type') &&
      /^\s*[[{]/.test(r.body)
        ? { ...r.headers, 'Content-Type': 'application/json' }
        : r.headers,
    body: r.body,
    expectStatus: r.expectStatus,
  }));
  const options = {
    scenarios: { load: scenario(p) },
    // A redirect could lead to another host: report it instead of following it.
    maxRedirects: 0,
    summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)', 'p(99)'],
    thresholds: thresholds(p),
  };
  return `// Generated by Friday for an approved load test. It calls only ${p.origin}.
import http from 'k6/http';
import { check, sleep } from 'k6';

const ORIGIN = ${json(p.origin)};
const REQUESTS = ${json(requests)};
const THINK_SECONDS = ${p.thinkTimeMs / 1000};

export const options = ${json(options)};

// Unexpected responses this virtual user already reported (one body sample each).
const REPORTED = {};

export default function () {
  for (const r of REQUESTS) {
    const res = http.request(r.method, ORIGIN + r.path, r.body, {
      headers: r.headers,
      tags: { name: r.name },
      timeout: '30s',
      ...(r.expectStatus === null ? {} : { responseCallback: http.expectedStatuses(r.expectStatus) }),
    });
    const ok = r.expectStatus === null ? res.status >= 200 && res.status < 400 : res.status === r.expectStatus;
    check(res, {
      [r.name + (r.expectStatus === null ? ': status 2xx or 3xx' : ': status ' + r.expectStatus)]: () => ok,
      // Counts the status codes this request got (always passes; read from the summary).
      ['${STATUS_CHECK}' + r.name + ':' + res.status]: () => true,
    });
    // The start of the first unexpected answer, to say why it failed.
    if (!ok && !REPORTED[r.name + res.status]) {
      REPORTED[r.name + res.status] = true;
      const text = String(res.body || res.error || '').replace(/\\s+/g, ' ').slice(0, 200);
      check(res, { ['${BODY_CHECK}' + r.name + ':' + res.status + ':' + text]: () => true });
    }
  }
  if (THINK_SECONDS > 0) sleep(THINK_SECONDS);
}

export function handleSummary(data) {
  return { [__ENV.FRIDAY_SUMMARY]: JSON.stringify(data) };
}
`;
}
